-- STELK Class Monitor: Supabase schema and access policies.
-- Run once in Supabase SQL Editor (or apply with Supabase CLI).
create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('administrator','pengurus','orang_tua','siswa'); exception when duplicate_object then null; end $$;
do $$ begin create type public.attendance_status as enum ('sudah','tidak_melaksanakan','berhalangan'); exception when duplicate_object then null; end $$;
do $$ begin create type public.prayer_category as enum ('berjamaah_masjid','berjamaah_rumah','sendiri'); exception when duplicate_object then null; end $$;
do $$ begin create type public.verification_status as enum ('menunggu','terverifikasi','perlu_perbaikan'); exception when duplicate_object then null; end $$;
create table if not exists public.students(id uuid primary key default gen_random_uuid(),student_number integer unique not null,full_name text not null,class_name text not null default 'X TJKT 5',active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.student_private(student_id uuid primary key references public.students(id) on delete cascade,religion text not null check(religion in ('Islam','Kristen','Katolik','Hindu','Buddha','Konghucu','Lainnya')),prayer_reporting_required boolean not null default true,updated_at timestamptz not null default now());
create table if not exists public.user_profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null,role public.app_role not null,student_id uuid references public.students(id) on delete restrict,officer_position text,created_at timestamptz not null default now(),constraint profile_scope check((role in('orang_tua','siswa') and student_id is not null) or role in('administrator','pengurus')));
create table if not exists public.attendance_zuhur(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id),activity_date date not null,status public.attendance_status,category public.prayer_category,activity_time time,verification public.verification_status not null default 'menunggu',entered_by uuid references auth.users(id),verified_by uuid references auth.users(id),verified_at timestamptz,created_at timestamptz not null default now(),unique(student_id,activity_date),check((status='sudah' and category is not null) or (status is distinct from 'sudah' and category is null) or status is null));
create table if not exists public.attendance_asar (like public.attendance_zuhur including all);
create table if not exists public.duty_schedules(id uuid primary key default gen_random_uuid(),duty_date date not null,student_id uuid not null references public.students(id),task_name text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(duty_date,student_id,task_name));
create table if not exists public.daily_duties(id uuid primary key default gen_random_uuid(),duty_date date not null,student_id uuid not null references public.students(id),task_name text not null,status text not null check(status in('sudah_dilaksanakan','belum_dilaksanakan','tidak_hadir','berhalangan')),verification public.verification_status not null default 'menunggu',entered_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(duty_date,student_id,task_name));
create table if not exists public.class_cash(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),transaction_type text not null check(transaction_type in('pemasukan','pengeluaran')),category text not null,description text,amount numeric(14,2) not null check(amount>0),transaction_date date not null,payment_period text,payment_status text,payment_method text,receipt_path text,entered_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.activity_evidence(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id),activity_type text not null check(activity_type in('zuhur','asar','piket','lainnya')),activity_date date not null,storage_path text not null,caption text,uploader_id uuid references auth.users(id),verification public.verification_status not null default 'menunggu',public_visible boolean not null default false,created_at timestamptz not null default now());
create or replace function public.current_app_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.user_profiles where user_id=auth.uid() limit 1 $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_app_role()='administrator',false) $$;
create or replace function public.is_officer() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_app_role() in('administrator','pengurus'),false) $$;
create or replace function public.can_view_student(target_student uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_officer() or exists(select 1 from public.user_profiles p where p.user_id=auth.uid() and p.student_id=target_student and p.role in('orang_tua','siswa')) $$;
create or replace function public.prayer_required_students() returns table(student_id uuid) language sql stable security definer set search_path=public as $$ select s.id from public.students s where s.active and public.can_view_student(s.id) and not exists(select 1 from public.student_private sp where sp.student_id=s.id and sp.prayer_reporting_required=false) $$;
revoke all on function public.prayer_required_students() from public,anon; grant execute on function public.prayer_required_students() to authenticated;
create or replace function public.block_exempt_prayer() returns trigger language plpgsql security definer set search_path=public as $$ begin if exists(select 1 from public.student_private sp where sp.student_id=new.student_id and sp.prayer_reporting_required=false) then raise exception 'Siswa ini dikecualikan dari pelaporan salat'; end if; return new; end $$;
drop trigger if exists zuhur_exempt on public.attendance_zuhur; create trigger zuhur_exempt before insert or update on public.attendance_zuhur for each row execute function public.block_exempt_prayer();
drop trigger if exists asar_exempt on public.attendance_asar; create trigger asar_exempt before insert or update on public.attendance_asar for each row execute function public.block_exempt_prayer();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['students','student_private','user_profiles','attendance_zuhur','attendance_asar','duty_schedules','daily_duties','class_cash','activity_evidence'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
DROP POLICY IF EXISTS "students scoped read" ON public.students; CREATE POLICY "students scoped read" ON public.students FOR SELECT TO authenticated USING(is_officer() or can_view_student(id));
DROP POLICY IF EXISTS "admin manages students" ON public.students; CREATE POLICY "admin manages students" ON public.students FOR ALL TO authenticated USING(is_admin()) WITH CHECK(is_admin());
DROP POLICY IF EXISTS "private admin only" ON public.student_private; CREATE POLICY "private admin only" ON public.student_private FOR ALL TO authenticated USING(is_admin()) WITH CHECK(is_admin());
DROP POLICY IF EXISTS "profile self admin read" ON public.user_profiles; CREATE POLICY "profile self admin read" ON public.user_profiles FOR SELECT TO authenticated USING(user_id=auth.uid() or is_admin());
DROP POLICY IF EXISTS "admin manages profiles" ON public.user_profiles; CREATE POLICY "admin manages profiles" ON public.user_profiles FOR ALL TO authenticated USING(is_admin()) WITH CHECK(is_admin());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['attendance_zuhur','attendance_asar'] LOOP EXECUTE format('drop policy if exists %I on public.%I','prayer scoped read',t); EXECUTE format('create policy %I on public.%I for select to authenticated using(can_view_student(student_id))','prayer scoped read',t); EXECUTE format('drop policy if exists %I on public.%I','officers insert',t); EXECUTE format('create policy %I on public.%I for insert to authenticated with check(is_officer())','officers insert',t); EXECUTE format('drop policy if exists %I on public.%I','officers update',t); EXECUTE format('create policy %I on public.%I for update to authenticated using(is_officer()) with check(is_officer())','officers update',t); EXECUTE format('drop policy if exists %I on public.%I','admin delete',t); EXECUTE format('create policy %I on public.%I for delete to authenticated using(is_admin())','admin delete',t); END LOOP; END $$;
DROP POLICY IF EXISTS "duty scoped read" ON public.daily_duties; CREATE POLICY "duty scoped read" ON public.daily_duties FOR SELECT TO authenticated USING(can_view_student(student_id));
DROP POLICY IF EXISTS "officers insert duty" ON public.daily_duties; CREATE POLICY "officers insert duty" ON public.daily_duties FOR INSERT TO authenticated WITH CHECK(is_officer());
DROP POLICY IF EXISTS "officers update duty" ON public.daily_duties; CREATE POLICY "officers update duty" ON public.daily_duties FOR UPDATE TO authenticated USING(is_officer()) WITH CHECK(is_officer());
DROP POLICY IF EXISTS "admin delete duty" ON public.daily_duties; CREATE POLICY "admin delete duty" ON public.daily_duties FOR DELETE TO authenticated USING(is_admin());
DROP POLICY IF EXISTS "schedule scoped read" ON public.duty_schedules; CREATE POLICY "schedule scoped read" ON public.duty_schedules FOR SELECT TO authenticated USING(is_officer() or can_view_student(student_id));
DROP POLICY IF EXISTS "admin manages schedules" ON public.duty_schedules; CREATE POLICY "admin manages schedules" ON public.duty_schedules FOR ALL TO authenticated USING(is_admin()) WITH CHECK(is_admin());
DROP POLICY IF EXISTS "cash read treasurer" ON public.class_cash; CREATE POLICY "cash read treasurer" ON public.class_cash FOR SELECT TO authenticated USING(is_admin() or exists(select 1 from user_profiles p where p.user_id=auth.uid() and p.role='pengurus' and p.officer_position in('Bendahara','Wakil Bendahara')));
DROP POLICY IF EXISTS "cash write treasurer" ON public.class_cash; CREATE POLICY "cash write treasurer" ON public.class_cash FOR INSERT TO authenticated WITH CHECK(is_admin() or exists(select 1 from user_profiles p where p.user_id=auth.uid() and p.role='pengurus' and p.officer_position in('Bendahara','Wakil Bendahara')));
DROP POLICY IF EXISTS "cash delete admin" ON public.class_cash; CREATE POLICY "cash delete admin" ON public.class_cash FOR DELETE TO authenticated USING(is_admin());
DROP POLICY IF EXISTS "evidence scoped read" ON public.activity_evidence; CREATE POLICY "evidence scoped read" ON public.activity_evidence FOR SELECT TO authenticated USING(is_officer() or (can_view_student(student_id) and public_visible));
DROP POLICY IF EXISTS "officers upload evidence" ON public.activity_evidence; CREATE POLICY "officers upload evidence" ON public.activity_evidence FOR INSERT TO authenticated WITH CHECK(is_officer());
DROP POLICY IF EXISTS "officers update evidence" ON public.activity_evidence; CREATE POLICY "officers update evidence" ON public.activity_evidence FOR UPDATE TO authenticated USING(is_officer()) WITH CHECK(is_officer());
DROP POLICY IF EXISTS "admin delete evidence" ON public.activity_evidence; CREATE POLICY "admin delete evidence" ON public.activity_evidence FOR DELETE TO authenticated USING(is_admin());
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('class-evidence','class-evidence',false,5242880,array['image/jpeg','image/png']) ON CONFLICT(id) DO NOTHING;
DROP POLICY IF EXISTS "class evidence officers read" ON storage.objects; CREATE POLICY "class evidence officers read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='class-evidence' and public.is_officer());
DROP POLICY IF EXISTS "class evidence linked read" ON storage.objects; CREATE POLICY "class evidence linked read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='class-evidence' and exists(select 1 from public.activity_evidence e where e.storage_path=name and e.public_visible and public.can_view_student(e.student_id)));
DROP POLICY IF EXISTS "class evidence upload" ON storage.objects; CREATE POLICY "class evidence upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='class-evidence' and public.is_officer());
DROP POLICY IF EXISTS "class evidence delete" ON storage.objects; CREATE POLICY "class evidence delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='class-evidence' and public.is_admin());
